import subprocess, json

def set_cell(pat, row, ch, note='', inst='', vol=40, eff='', effp=0):
    args = {
        "pattern": pat,
        "row": row,
        "channel": ch
    }
    if note != '': args["note"] = note
    if inst != '': args["instrument"] = inst
    if vol != '': args["volume"] = vol
    if eff != '': args["effect"] = eff
    if effp != '': args["effect_param"] = effp
    res = subprocess.run(['ft2', 'call', 'pattern_set_cell', json.dumps(args)], capture_output=True, text=True)
    # print(pat, row, ch, res.stdout, res.stderr)

# Pattern definitions
# Channel mapping: 0: Lead (inst 1), 1: Bass (inst 2), 2: Pluck (inst 3), 3: Kick (4), 4: Snare (5), 5: HiHat (6), 6: empty, 7: empty

# Notes for melody (lead) - pattern 0 has nothing for simplicity
# Pattern 1: melody
# We'll set notes every 4 rows for simplicity (8 notes per pattern)

def write_pat0():
    # Intro: bass + pluck + drums, no lead
    for row in [0, 8, 16, 24]:
        # bass on rows 0,8,16,24: C3, E3, G3, A3
        bass_notes = {0: 'C-3', 8: 'E-3', 16: 'G-3', 24: 'A-3'}
        pluck_notes = {0: 'C-4', 8: 'E-4', 16: 'G-4', 24: 'A-4'}
        if row in bass_notes:
            set_cell(0, row, 1, note=bass_notes[row], inst=2, vol=50)
        if row in pluck_notes:
            set_cell(0, row, 2, note=pluck_notes[row], inst=3, vol=35)
    # drums: kick on 0, 8, 16, 24; snare none; hat on 2,6,10,14,18,22,26,30
    for row in [0,8,16,24]:
        set_cell(0, row, 3, note='C-4', inst=4, vol=45)
    for row in [2,6,10,14,18,22,26,30]:
        set_cell(0, row, 5, note='C-5', inst=6, vol=30)

def write_pat1():
    # Main: full melody
    # Lead melody: C5, E5, G5, A5, G5, E5, C5, D5 (every 4 rows)
    lead = {
        0: 'C-5', 4: 'E-5', 8: 'G-5', 12: 'A-5',
        16: 'G-5', 20: 'E-5', 24: 'C-5', 28: 'D-5'
    }
    for r, n in lead.items():
        set_cell(1, r, 0, note=n, inst=1, vol=50)
    # Bass: A2, F2, C3, G2 (walking)
    bass = {0: 'A-2', 8: 'F-2', 16: 'C-3', 24: 'G-2'}
    for r, n in bass.items():
        set_cell(1, r, 1, note=n, inst=2, vol=55)
    # Pluck: A3, F3, C3, G3
    pluck = {0: 'A-3', 8: 'F-3', 16: 'C-3', 24: 'G-3'}
    for r, n in pluck.items():
        set_cell(1, r, 2, note=n, inst=3, vol=40)
    # Drums
    for r in [0, 8, 16, 24]:
        set_cell(1, r, 3, note='C-4', inst=4, vol=50)
    for r in [4, 12, 20, 28]:
        set_cell(1, r, 4, note='C-4', inst=5, vol=45)
    for r in [2, 6, 10, 14, 18, 22, 26, 30]:
        set_cell(1, r, 5, note='C-5', inst=6, vol=25)

def write_pat2():
    # Variation: slightly different melody
    lead = {0: 'E-5', 4: 'G-5', 8: 'A-5', 12: 'C-6', 16: 'A-5', 20: 'G-5', 24: 'E-5', 28: 'F-5'}
    for r, n in lead.items():
        set_cell(2, r, 0, note=n, inst=1, vol=50)
    bass = {0: 'F-2', 8: 'C-3', 16: 'G-2', 24: 'D-3'}
    for r, n in bass.items():
        set_cell(2, r, 1, note=n, inst=2, vol=55)
    pluck = {0: 'F-3', 8: 'C-3', 16: 'G-3', 24: 'D-4'}
    for r, n in pluck.items():
        set_cell(2, r, 2, note=n, inst=3, vol=40)
    for r in [0, 8, 16, 24]:
        set_cell(2, r, 3, note='C-4', inst=4, vol=50)
    for r in [4, 12, 20, 28]:
        set_cell(2, r, 4, note='C-4', inst=5, vol=45)
    for r in [2, 6, 10, 14, 18, 22, 26, 30]:
        set_cell(2, r, 5, note='C-5', inst=6, vol=25)

def write_pat3():
    # Bridge: higher, shorter notes maybe same rhythm
    lead = {0: 'G-5', 4: 'A-5', 8: 'C-6', 12: 'D-6', 16: 'C-6', 20: 'A-5', 24: 'G-5', 28: 'F-5'}
    for r, n in lead.items():
        set_cell(3, r, 0, note=n, inst=1, vol=50)
    bass = {0: 'C-3', 8: 'E-3', 16: 'A-2', 24: 'F-2'}
    for r, n in bass.items():
        set_cell(3, r, 1, note=n, inst=2, vol=55)
    pluck = {0: 'C-4', 8: 'E-4', 16: 'A-3', 24: 'F-3'}
    for r, n in pluck.items():
        set_cell(3, r, 2, note=n, inst=3, vol=40)
    for r in [0, 8, 16, 24]:
        set_cell(3, r, 3, note='C-4', inst=4, vol=50)
    for r in [4, 12, 20, 28]:
        set_cell(3, r, 4, note='C-4', inst=5, vol=45)
    for r in [2, 6, 10, 14, 18, 22, 26, 30]:
        set_cell(3, r, 5, note='C-5', inst=6, vol=25)

def write_pat4():
    # Break: simpler, half speed? Actually same speed but fewer notes.
    # Lead: only on 0, 8, 16, 24
    lead = {0: 'C-5', 8: 'G-5', 16: 'E-5', 24: 'C-5'}
    for r, n in lead.items():
        set_cell(4, r, 0, note=n, inst=1, vol=50)
    bass = {0: 'A-2', 8: 'F-2', 16: 'C-3', 24: 'G-2'}
    for r, n in bass.items():
        set_cell(4, r, 1, note=n, inst=2, vol=55)
    pluck = {0: 'A-3', 8: 'F-3', 16: 'C-3', 24: 'G-3'}
    for r, n in pluck.items():
        set_cell(4, r, 2, note=n, inst=3, vol=40)
    # Drums: kick and snare only
    for r in [0, 8, 16, 24]:
        set_cell(4, r, 3, note='C-4', inst=4, vol=50)
    for r in [4, 12, 20, 28]:
        set_cell(4, r, 4, note='C-4', inst=5, vol=45)
    for r in [2, 6, 10, 14, 18, 22, 26, 30]:
        set_cell(4, r, 5, note='C-5', inst=6, vol=25)

def write_pat5():
    # Outro: similar to intro but with lead
    lead = {0: 'C-5', 12: 'E-5', 24: 'G-5'}
    for r, n in lead.items():
        set_cell(5, r, 0, note=n, inst=1, vol=50)
    bass = {0: 'C-3', 8: 'E-3', 16: 'G-3', 24: 'A-3'}
    for r, n in bass.items():
        set_cell(5, r, 1, note=n, inst=2, vol=55)
    pluck = {0: 'C-4', 8: 'E-4', 16: 'G-4', 24: 'A-4'}
    for r, n in pluck.items():
        set_cell(5, r, 2, note=n, inst=3, vol=40)
    for r in [0,8,16,24]:
        set_cell(5, r, 3, note='C-4', inst=4, vol=50)
    for r in [4,12,20,28]:
        set_cell(5, r, 4, note='C-4', inst=5, vol=45)
    for r in [2,6,10,14,18,22,26,30]:
        set_cell(5, r, 5, note='C-5', inst=6, vol=25)

write_pat0()
write_pat1()
write_pat2()
write_pat3()
write_pat4()
write_pat5()
print("Done")
PYEOF
